{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Gives FR Doc. 2026-15665, 91 FR 49178–49227, published Aug. 3, 2026, effective Sept. 2, 2026, docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Identifies FR Doc. 2026-04377, 91 FR 10904, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Lists 2026-17335, published Aug. 25, 2026, effective Sept. 2, 2026, describing it as correcting typographical and clerical errors in instructions and regulatory text."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Lists 2026-18800, published and effective Sept. 15, 2026, and says it restores 330.602(1)(i)–(ii), the CTAP “displaced” paragraphs removed by the final rule."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "States that a RIF noticed before Sept. 2, 2026 stays under the earlier rules and one noticed on or after that date uses the amended rules, citing the DATES line and Implementation Considerations at 91 FR 49206–07."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective Sept. 2, 2026 and in force, and says it rewrites subpart I (351.901–351.909) and 351.802(a)(6)."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it revises 351.806, gives Nov. 18, 2026 as the effective date and says it is not yet in force."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it changes the 351.203 “rating of record” definition and 351.503, and gives Nov. 18, 2026 as the effective date, not yet in force."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Claims carry document numbers and FR page citations throughout; no substantial citation-discipline deduction."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented document or quotation detected. The answer’s statement that the correction changed “of this part” to “of this title” is inaccurate (the correction says “of this chapter”), but that is a misreading of a real correction, not fabrication."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7+5+5=17 performance credit, 0 veterans’ points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5+0+3=8, plus 5 points, total 13; Level 2 is correctly worth 0."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: 17 performance credit and 0 veterans’ points, correctly explaining that retired pay based on 20+ years fails 351.504(b)(2) and (b)(4) does not make him eligible."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings, proxy (7+0)/2=3.5, performance credit 10.5, plus 3 points, total 13.5."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: 15 performance credit, 0 veterans’ points, total 15, and tenure subgroup II."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one rating, 5×3=15 under 351.503(f)(3), total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Order is Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi; explains Abbott over Castillo by earlier SCD and Fontaine over Eze by tenure subgroup I over II."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "Names Bianchi and Dalton as released."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would rank above Abbott under the earlier rules because those rules used tenure group, then veterans’ subgroup AD/A/B, then service as augmented by performance, citing 91 FR 49198."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Says she may inspect the complete retention register, including other employees’ names and the performance credit/SCD information, under 351.506(c)."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "The answer uses CFR paragraphs and FR pages throughout; no substantial citation-discipline problem."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented document, paragraph or quotation identified."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "Case A: not preference eligible, 0 points, subgroup B, 351.504(b)."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "Case B: not preference eligible, 0 points, subgroup B; the answer cites 351.504(b)(4) and correctly rejects eligibility despite the 40% disability."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "Case C: preference eligible, 5 points, subgroup AD, relying on 351.504(b)(1)(i), (b)(4), and (a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "Case D: not preference eligible, 0 points, subgroup B, because retired pay is based on 24 years and no other basis applies."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "Case E: preference eligible, 3 points, subgroup A; 351.504(b)(2) applies because retired pay is based on only 16 years and the disability is under 30%."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A: only 2 years of campaign service are creditable, giving Sept. 7, 2008."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C: all 14 years are creditable as a preference eligible, giving Sept. 7, 1996."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Says subgroups are labels/identifiers, the points are added to performance credit, and the subgroup is not a separate ranking step or tie-breaker."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "Provisions and page citations are supplied; no substantial citation-discipline issue."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation found."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "Farah: 7+3+3=13 using the Aug. 10, 2026, Nov. 14, 2025, and Nov. 15, 2024 ratings."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Correctly computes Sept. 3, 2026 minus 45 days as July 20, 2026."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "Excludes the Aug. 10, 2026 rating and uses Level 3, Level 3, Level 4 for 11 points."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Says the rating cannot be used because it was not on record until Aug. 15, after the July 20 cutoff, under 351.503(c)(2)–(3)."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Gina: Aug. 15, 2022 is outside the four-year period; proxy is (5+3)/2=4, so 5+3+4=12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Hank: credit must be based on the modal rating under 351.503(f)(1) and the 351.203 definition; the answer does not wrongly give zero or apply the one- or two-rating formula."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Explicitly says the FR text does not state the modal value or the arithmetic for a no-rating employee, so no number can be computed."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "Citations to CFR paragraphs and FR pages are provided throughout."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented source identified."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Says the Aug. 28, 2026 notice is governed by the earlier rules even though the RIF takes effect Oct. 27, 2026."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Applies 12 years for Level 3 and 20 for Level 5, giving Lee 1986 and Park 1999, and releases Park."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "Sept. 2, 2026 notice uses the amended rules; Lee 9, Park 21, Lee released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "Sept. 3, 2026 notice: same amended-rule result, Lee released."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Says no recalculation under 351.805(b) because the amended notice solely moved the effective date; adds that the Oct. 15 rating is outside the window."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Version of the rules is fixed by the date the agency issues the RIF notice, citing the DATES line and implementation section."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "Four-year period ends at notice issuance or agency cutoff date, citing 351.503(c)(1)–(2)."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing are fixed when the employee receives the specific RIF notice, citing 351.502 and 351.507(a)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant FR pages and CFR provisions."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented source identified."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Treats positions 1–3 as within reach and correctly excludes 4 (too many grades), 5 (higher standing), 6 (different schedule), and 7 (different competitive area)."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "Says the agency must offer the GS-12 held by Ellis as the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "Says the limit becomes five grades, GS-9 becomes reachable, and the offer remains the GS-12."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "Says a Level 1 rating gives no assignment right because 351.701(a) requires minimally satisfactory (Level 2) or higher."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says 351.701 applies to competitive service employees and excepted service rights exist only if the agency adopts them under 351.705(a)."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says former 351.701(d), barring Level 2 employees from higher-rated employees’ positions, was eliminated, citing 91 FR 49204."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says bumping and retreating were replaced by a single assignment right to a lower-standing employee’s position."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "The answer provides CFR and FR citations for the key points."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No invented source or quote found."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Concludes MSPB hears the appeal because the notice was issued Aug. 31, 2026, before the Sept. 2 appeals-rule applicability date."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites the MSPB’s 2026 rule, 2026-16456 (91 FR 51997), and says the Board continues to adjudicate RIF appeals where the notice was issued before the effective date."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "Says the appeal goes to OPM under 351.901(a)."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Correctly counts Dec. 19 as day 1, Jan. 17, 2027 as day 30, and notes it is Sunday."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives Tuesday, Jan. 19, 2027, because Jan. 18 is MLK Day."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Says filing must be through OPM’s electronic filing system and timely by 11:59 p.m. Eastern on the last day."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "States the employee’s preponderance burden on timeliness, jurisdiction, RIF noncompliance, and prejudice under 351.901(b)."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "Says no hearing as of right; OPM proceeds on the written record unless a hearing is necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(2) bars raising the RIF action under a negotiated grievance procedure or grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble’s statements that existing CBAs are not retroactively invalidated, bargaining is limited on renegotiation, and particular existing-agreement questions remain for the chapter 71 forum."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says no judicial review under 351.901(c)(4) and no further appeal of OPM’s final decision under 351.909(e)."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Says she may still appeal under 351.902(b)(3) within 30 days after the OSC decision becomes final and gives April 9, 2027."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Locates the controlling applicability provision in the appeals rule’s DATES line at 91 FR 49230 and does not attribute it to regulatory text."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "Citations are ample throughout."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation identified."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as revising 351.806, effective Nov. 18, 2026, and says it is not in force today."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the adopted rule: duty status under ordinary circumstances, with administrative leave permitted when appropriate and consistent with part 630, subpart N."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Says the current version is described as keeping the employee in duty status “when possible,” citing the rulemaking documents."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says no consent is required under the adopted 351.806(b) and points to 630.1403(c)(10) as the companion leave authority."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "Says the adopted text has no stated day limit for leave under 630.1403(c)(10)."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Discusses the 12-week governmentwide limit and correctly notes that the preamble attaches it expressly to 630.1403(c)(9) and (c)(11)."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "Flags in the uncertainty section that the 12-week cap’s application to (c)(10) is not stated and the rule is not yet in force."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Points to OPM’s Agency Policy Template as prior guidance permitting administrative leave during a RIF notice period, although it omits the CPM number (optional)."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says the leave rule does not alter RIF competition, retention registers, standing, or appeal rights, citing 91 FR 65926."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "The answer includes FR pages and CFR provisions; the malformed “91 FR 49-note” reference is a citation typo but not a general failure to cite."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented source is relied on; the odd “91 FR 49-note” wording is a citation error, not a fabricated source supporting a separate claim."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Step 1 does not comply: 57 days is within 90 days and 351.402(c) required submission to OPM for approval with a bona fide organizational basis statement."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Step 3 does not comply: a supervisory probationary period is not an initial probationary period, so Ortiz had to be ranked."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Step 4 does not comply: the Sept. 13 cutoff bars using the Oct. 2 rating, and uniform application is also required under 351.503(c)(2)–(4)."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Step 5 does not comply: proxy is (7+5)/2=6, so Quist’s credit is 18, not a presumed Level 3 and 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Step 6 does not comply: under a five-level pattern, 351.503(d) does not permit the added points; an advance written policy does not cure it."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Step 8 does not comply: 351.602(a) bars releasing a competing employee while retaining one with a limited temporary or term promotion."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Step 10 does not comply: 351.702(a)(4)(iii) bars an assessment consisting solely of or principally relying on an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Step 11 does not comply: 351.608(a)(3) bars sequencing or stacking exceptions; only one exception, up to 90 days, may be used."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Step 12 does not comply: for notices issued on or after Sept. 2, 2026, the appeal is to OPM under part 351, subpart I, not MSPB."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Correctly says steps 2, 7 and 9 are in order and gives the deciding provisions for all three."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "The answer does not call step 2 a violation; it correctly says step 2 complies."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "The answer correctly says step 7 complies under 351.601(c)."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "The answer correctly says step 9 complies under 351.702(a)(4)(v)."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Each step is tied to a CFR provision and FR page."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation identified."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Says paragraph (1) contained only its introductory text because instruction 11 revised it and set out only that text, removing (1)(i) and (1)(ii)."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective Sept. 15, 2026, restoring (1)(i) and (1)(ii)."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "Gives OPM’s good-cause explanation that the correction makes no substantive change and restores text that was in effect before Sept. 2 and not proposed for removal."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Says declining a lower-representative-rate position does not end displacement under paragraph (1)(i)."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Says declining a same-representative-rate, same-schedule position means she is not displaced under paragraph (1)(i)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "CFR and FR citations are supplied."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation found."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "no",
      "rationale": "Counted 8 valid differences, not 10. Submission items in order: (1) 351.202(d)(1)(ii) qualifier dropped — counted, key item 21 (1 piece); (2) 351.202(d)(2)(iii) temporary/term appointment narrowed — counted, key item 2 (1); (3) 351.202(d)(3) reworded plus new (d)(4) notice — counted, key items 3 and 4 (2 pieces); (4) 351.504(a) “should” to “must” — counted, key item 10 (1); (5) 351.701(a) “Minimally Successful” to “Minimally Satisfactory” — counted, key item 9 (1); (6) 351.702(a)(4)(iii) self-assessment wording — counted, key item 17 (1); (7) 351.702(a)(4)(iv) subparagraph letters to numbers — not counted, format-only change; (8) 351.507(b) “any of this paragraph” to “any of these provisions” — counted, key item 29 (1). Total: 1+1+2+1+1+1+0+1=8."
    },
    "q11_valid_16": {
      "verdict": "no",
      "rationale": "Same count as q11_valid_10: 8 valid differences, below 16."
    },
    "q11_valid_22": {
      "verdict": "no",
      "rationale": "Same count: 8 valid differences, below 22."
    },
    "q11_valid_28": {
      "verdict": "no",
      "rationale": "Same count: 8 valid differences, below 28."
    },
    "q11_valid_34": {
      "verdict": "no",
      "rationale": "Same count: 8 valid differences, below 34."
    },
    "q11_deep": {
      "verdict": "no",
      "rationale": "Only 4 deep items are stated: 351.202(d)(1)(ii) qualifier dropped (deep i), 351.504(a) should/must (deep iii), 351.701(a) Level 2 wording (deep ii), and 351.702(a)(4)(iii) reworded (deep vi). Items 2, 3, 7 and 8 are not on the deep list. Total 4, below 6."
    },
    "q11_cite": {
      "verdict": "no",
      "rationale": "Uses document numbers and page citations for each compared item."
    },
    "q11_fab": {
      "verdict": "no",
      "rationale": "No invented source; item 7 is a real but non-substantive textual difference."
    }
  },
  "Q12": {
    "q12_quinn": {
      "verdict": "yes",
      "rationale": "Quinn is serving an initial probationary period, is not a competing employee, is not ranked, and may be retained under 351.202(d)(2)(ii) and (d)(3)."
    },
    "q12_ab": {
      "verdict": "yes",
      "rationale": "Alvarez 7+7+5=19, no points; Brandt 3+5+0=8 plus 5 = 13."
    },
    "q12_chen": {
      "verdict": "yes",
      "rationale": "Chen 18: Sept. 30, 2022 rating outside the window, two ratings 7 and 5, proxy 6, total 7+5+6=18."
    },
    "q12_dube": {
      "verdict": "yes",
      "rationale": "Dube: two ratings, proxy 5, performance credit 15, plus 3 = 18."
    },
    "q12_estrada": {
      "verdict": "yes",
      "rationale": "Estrada: excludes the Oct. 20, 2026 rating, uses 5+3+5=13, plus 3 = 16."
    },
    "q12_farouk_score": {
      "verdict": "yes",
      "rationale": "Farouk: one rating, 3×3=9, no veterans’ points, lowest on the face of the register."
    },
    "q12_tie": {
      "verdict": "yes",
      "rationale": "Order Alvarez 19, Chen 18, Dube 18, Estrada 16, Brandt 13, Farouk 9; Chen ahead of Dube because subgroup I ranks ahead of II."
    },
    "q12_protect": {
      "verdict": "yes",
      "rationale": "Farouk is restoration protected; 14 months of uniformed service put him within the one-year period on the notice date, and 351.606(a)(2) bars releasing him while another competing employee may be released."
    },
    "q12_released": {
      "verdict": "yes",
      "rationale": "Releases exactly Brandt, Estrada and Dube."
    },
    "q12_assign_dube": {
      "verdict": "yes",
      "rationale": "Dube must be offered Gomez’s GS-12, the least reduction among lower-standing positions."
    },
    "q12_assign_estrada": {
      "verdict": "yes",
      "rationale": "Estrada must be offered Hill’s GS-11; Gomez has higher standing and is unavailable."
    },
    "q12_assign_brandt": {
      "verdict": "yes",
      "rationale": "Brandt must be offered Ikeda’s GS-9; the five-grade limit applies because he is a preference eligible with a 30% compensable disability."
    },
    "q12_final": {
      "verdict": "yes",
